INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (157, 24, 32, 20, 'Apply the decided OpenCode transport ceiling', 'Replace the hard-coded 600-second OpenCode HTTP/SSE timeout with Decision #21''s 5400-second catastrophic ceiling, name the constant, and add a constructor-level regression without changing injected test transports.', 'done', '2026-07-30', NULL, 1, '2026-07-30');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (158, 24, 32, 21, 'Make synchronous OpenCode turns interruptible', 'Preserve the pre-opened SSE subscription and synchronous /session/{id}/message path, but return NativeTurn before message dispatch and perform the blocking POST from stream() so the broker persists exact session/run identity and exposes active.turn before manual Stop calls /abort. Keep ordinary stacked messages non-interrupting and retain exact-resume/early-idle behavior.', 'done', '2026-07-30', NULL, 1, '2026-07-30');
