INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (163, 24, 42, 4, 'Phased Interface loading', 'After feature #26 mode shell lands or on an explicit stack, defer flavor defaults/models, add shared retryable Configure loading, direct deep-link resolution, recent-first history, background paged stars, More, selected context, dedupe, and open-only polling. Areas: .super-coder/ui/app.js, style.css, UI/request tests. Gate: failure isolation, switch semantics, cursor retention, and zero eager catalogue requests pass.', 'done', '2026-07-31', NULL, 9, '2026-07-30');
