INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (190, 31, 46, 7, 'U7 Stage 7 — liveness monitor', '5-min evaluation of accepted expectations incl. review requests; strong/supporting evidence; 10-min grace; one nudge per silence episode; one deduped Planner escalation; fallback delivery for Planner escalation only', 'done', '2026-08-01', NULL, 9, '2026-07-31');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (191, 31, 46, 8, 'U8 Stage 8 — pause, resume, recovery', 'any-participant pause + system auto-pause via same machinery; interrupt intent persistence; pause-report template; resume reconciliation (informs, never silently blocks); abort incl. prepared-exit; drift evidence for spec edits', 'done', '2026-08-01', NULL, 9, '2026-07-31');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (192, 31, 46, 9, 'U9 Stage 9 — conformance follow-ups, report compiler, five sprint skills', 'conformance findings land as follow-ups never in-Sprint fixes; bounded evidence packet; sprint_prep/sprint_pln/sprint_dev/sprint_rev/sprint_close skills as engine assets', 'done', '2026-08-01', NULL, 9, '2026-07-31');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (193, 31, 46, 10, 'U10 Stage 10 — live vertical proof + adversarial acceptance', 'one serial + one parallel Sprint with real browser conversations and real GitHub repo; full adversarial acceptance list from spec exercised', 'done', '2026-08-01', NULL, 9, '2026-07-31');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (194, 24, 56, 1, 'Executable segmented-response traces', 'Add historical/live API fixtures and instrumented Playwright traces for plain prose, prose-tool-prose, multiple tools, tool-before-prose, permission/input pauses, pending-boundary refresh, truncation, reconnect, and same-adapter concurrency across separate conversations. Gate: current v1 fails exact item count, stable ids, order, cursor, actual DOM identity, and hidden-Chat/frame assertions.', 'done', '2026-08-01', NULL, 1, '2026-07-31');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (195, 24, 56, 2, 'Transcript projection version 2', 'Fold normalized events into durable sequence-anchored assistant segments, derive the active cursor from the full pre-cap event prefix, extend terminal completeness checks to boundary evidence, and preserve caps, redaction, warnings, one SQLite snapshot, and the fixed five-query read count.', 'done', '2026-08-01', NULL, 1, '2026-07-31');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (196, 24, 56, 3, 'Keyed live assistant segments', 'Hydrate and reduce the same segment anchors in the browser; keep tool chatter hidden, waiting activity ordered, Markdown parsing segment-local, completed nodes stable, paused scroll intact, hidden Chat quiet, and reconciliation single-flight. Prove actual node identity and frame behavior in the instrumented Playwright Chat harness.', 'done', '2026-08-01', NULL, 1, '2026-07-31');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (197, 24, 56, 4, 'Cross-harness segmented-response gate', 'Run the multi-phase response journey through Claude, Codex, Kimi, and OpenCode traces plus a live browser smoke with refresh at a pending tool boundary and Chat/Diff switching. Gate: ordered bubbles, no lost/duplicate text, bounded projection, and unchanged delivery/terminal semantics.', 'done', '2026-08-01', NULL, 1, '2026-07-31');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (198, 31, 46, 11, 'U11 Remediation — production surface completion (close-out + participation)', 'Remediation unit A (conformance dual-FAIL docs #57/#58, decision #45, spec REV9). Production surfaces for store-deep capabilities: QAQC approval recording via authenticated sprint surface + Review-shell signer verification (A-M1+A-Md1; retire/repair the dead ''sc mem doc qaqc'' POST path); sprint inbox read/mark-read(accept)/decline verbs (A-M2); shell-judged work-unit completion incl. report-only/no-code marker + durable result, and cancelled disposition writability (A-M4/B-C-m9); replan surface (A-Md4); final sprint report write path (report_kind=''final'') wired into sc sprint complete — ADVISORY per REV9, never a transition gate (B-C-M1); FnB-only follow-up disposition verb accepted/resolved/dismissed per REV9 semantics (B-C-M2). Thin authenticated callers over the existing tested stores, R6 auth pattern, R1 allowlist discipline, skills updated to name the real commands (three-artifact rule if skill text changes).', 'done', '2026-08-01', NULL, 9, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (199, 31, 46, 12, 'U12 Remediation — completion/watcher/recovery behavior fixes', 'Remediation unit B (conformance dual-FAIL, decision #45, spec REV9) — behavior fixes, builds after U11 merges (serial; shared files). R7 completion semantics: merged observation completes ONLY merge_ready units; grant-bypassed merges record merge.grant_bypassed + active Planner notice, never auto-complete (A-M3). Watcher head-change transitions: dedupe on (normalized_state, head); head move while merge_ready voids stale approval, returns unit to in_review, wakes Reviewer for delta review (B-C-m1/C-m2). Stranded-wake recovery: resume re-queues terminally-failed wakes for the resumed sprint and surfaces them in reconciliation evidence (B-C-m5). Sprint conversation lifecycle cleanup: terminal lifecycle closes sprint conversations so participants stop projecting browser_active (A-Md5). R1 allowlist discipline.', 'done', '2026-08-01', NULL, 9, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (200, 31, 59, 13, 'U13 Sprint board read API', 'Add browser-authenticated Sprint list/detail/events/summaries projections over one consistent read snapshot; cursor pagination, allowlisted event fields, structured errors, no external calls or copied state.', 'done', '2026-08-01', NULL, 1, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (201, 31, 59, 14, 'U14 Global header and Sprint routing', 'Reorder the global leading tabs to Chats, Sprints, Shells; add #sprints and exact-ID routes, selector, empty/error states, Roadmap feature deep link, stable titles/history, and visible-tab polling lifecycle.', 'done', '2026-08-01', NULL, 1, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (202, 31, 59, 15, 'U15 Work-unit board and audit modal', 'Render Done/Review/Dev/Waiting/Blocked columns, v2 disposition mapping, accessible dependency text plus measured SVG highlighting, participant/spec/task/PR links, and read-only work-unit audit detail.', 'done', '2026-08-01', NULL, 1, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (203, 31, 59, 16, 'U16 FnB lifecycle actions and feeds', 'Add lazy paged Sprint events and judgments/reports summaries plus confirmed FnB Pause/Resume/Abort flows that delegate to existing coordinators, preserve UI state, and never expose extra lifecycle authority.', 'done', '2026-08-01', NULL, 1, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (204, 31, 59, 17, 'U17 Sprint board adversarial and visual proof', 'Prove auth, snapshot consistency, payload sanitization, cursors, all lifecycle/disposition mappings, idempotent actions, no-read-side effects, polling teardown/staleness, accessibility, restart behavior, and wide/narrow visual states.', 'done', '2026-08-01', NULL, 1, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (205, 31, 59, 18, 'U18 Review remediation', 'Fix SC-037 feed-row accordion preservation and SC-038 emitted-event allowlist drift; add regression tests.', 'done', '2026-08-01', NULL, 5, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (206, 31, 59, 19, 'U19 Review verification', 'Demonstrate SC-039 visual QA across all six required scenarios, restart route/state persistence, lifecycle header fixtures, then run focused and project gates.', 'done', '2026-08-01', NULL, 5, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (207, 32, 62, 1, 'Refactor modal frame contract', 'Replace footNodes with explicit footerStart/footerEnd slots, add openActionModal(dismissNode, actionNode), and centralize role, aria-modal, aria-labelledby, and focus restoration while preserving Escape and overlay close behavior.', 'done', '2026-08-01', 'never built — erroneously flipped to in_progress by DEV3''s stray ''task start 207'' (msg #678, meant for sprint-63-unrelated F31 task #210); API has no reopen transition, so re-added verbatim as the new seq-1 row of doc 62', 1, '2026-08-01');
