INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (216, 24, 32, 26, 'Hardening verification', 'Run focused and full conversation tests on current main, render-check, verification gates available in the dev worktree, and diff-check; open the follow-up PR', 'done', '2026-08-01', NULL, 12, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (217, 24, 56, 5, 'Per-run completeness gate (conformance F1 fix)', 'Gate segmentation-evidence completeness per RUN, not per message: omit an incomplete terminal run''s segments even when a non-terminal sibling is active, while still showing the active run''s bounded suffix. Regression test: multi-run message, one active run, source cap cutting the terminal sibling''s boundary events — v2 must omit the capped run under the explicit truncation contract instead of projecting a merged bubble.', 'done', '2026-08-01', NULL, 10, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (218, 31, 68, 1, 'Callable dispatcher floor', 'Heal existing forks and linked shell worktrees so the callable sc dispatcher matches the pinned materialized engine; verify current Sprint help from both roots without tracked-work dirtiness.', 'done', '2026-08-01', NULL, 9, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (219, 31, 68, 2, 'Participant relay and general wake', 'Expose one freeform participant send command over atomic Sprint message+wake delivery; route the general role-skill/inbox wake to an existing current chat or create and select a linked Sprint chat when absent; preserve typed state-changing commands.', 'done', '2026-08-01', NULL, 9, '2026-08-01');
