INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (225, 31, 68, 8, 'Review finding triage', 'Reproduce findings #104-#114 against PR #904 head, honor decision #53, and classify each as valid, already addressed, accepted design, or out of scope.', 'done', '2026-08-01', NULL, 5, '2026-08-01');
