INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (232, 33, 69, 2, 'Upstream tombstone registry and DB reconciler', 'Add the tracked validated tombstone registry and shared idempotent reconciliation API. Enforce active/tombstone disjointness, reserve removed names, delete child grants before skill rows, report changes, and preserve non-tombstoned fork-local rows exactly.', 'done', '2026-08-01', NULL, 9, '2026-08-01');
