INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (234, 33, 69, 4, 'Catalogue source removals and compatibility rewrites', 'Delete engine_surgery, test_authoring_pg, and test_authoring_sqlite assets; regenerate the active seed; remove obsolete grants and references from source-mode compose, generic test_authoring, query_authoring_pg, PG feature registry, public docs, retained manifests, and tests. Historical migrations remain untouched.', 'done', '2026-08-01', NULL, 9, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (235, 33, 69, 5, 'Curation governance — recommendations only', 'Remove the sc skill add command and tests. Rewrite curate, boot curation guidance, and issue_reporting so recurring L&S becomes a deduplicated upstream recommendation issue; keep compressed L&S until delivery. Preserve the explicit admin asset-to-seed-to-snapshot fork-skill workflow.', 'done', '2026-08-01', NULL, 9, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (236, 33, 69, 6, 'Exact managed projection reconciliation', 'Build the bounded shared reconciler for .claude, .agents, .opencode, active catalogue renders, and banner-owned legacy skills_sc. Integrate boot, update, CLI skill mutations, feature enable/disable, and GUI grant endpoints; sweep existing dormant worktrees without creating them; refuse symlink/path escape and preserve foreign files.', 'done', '2026-08-02', NULL, 9, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (237, 33, 69, 7, 'Adversarial downstream verification and release gate', 'Run focused suites plus seed-skills, render-check, verify, and diff-check. Exercise update and rebuild against the dirty-fork fixture twice; prove all 13 tombstones disappear from DB and disk, local controls survive byte-for-byte, projection failures are loud and retryable, and repeated convergence is a no-op.', 'done', '2026-08-02', NULL, 9, '2026-08-01');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (238, 31, 73, 1, 'Terminal completion and liveness state', 'Defer interruption of the completing owning Planner run while preserving close intent and all other terminal interruption behavior; resolve accepted work-assignment liveness when its unit enters in_review; add focused lifecycle, broker-finalization, trigger, migration, retry, and no-stale-nudge coverage.', 'done', '2026-08-02', NULL, 10, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (239, 31, 73, 2, 'Native roles, evidence, and skill audit', 'Update sprint_prep/pln/dev/rev/close so native runtime, wake recovery, liveness, and PR observation are the sole scheduled coordinators; use affirmative action/stop directives and retain only precisely targeted prohibitions for unsafe, authority-breaking, or duplicate coordination. Separate pre-declaration QAQC, expose exact-ID plus feature-scoped resolved flag evidence, and request conformance through the durable relay. Finish with an author+independent-Reviewer audit of organization, cohesiveness, lifecycle structure, token efficiency, prohibition quality, and intent preservation; report before/after line/word/character counts without a reduction quota, trace rewritten intent, then regenerate one ordered skill reseed.', 'done', '2026-08-02', NULL, 10, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (240, 31, 73, 3, 'Read-only deps help and nested tests', 'Return sc deps help before mutation and replace both root-only Python-presence gates with one pruned recursive tests/test_*.py check while preserving the existing pytest/unittest and frontend execution paths. Parallelizable with task 1.', 'done', '2026-08-02', NULL, 10, '2026-08-02');
