INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (248, 31, 84, 0, 'Preparation', 'Confirm mapped entry points, inspect current normalization and watcher tests, and pass the git sync/branch gate', 'done', '2026-08-02', NULL, 11, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (249, 31, 84, 1, 'Normalize check rollup states', 'Implement conclusion-to-state-to-status classification with failure precedence and uncertainty projected as pending', 'done', '2026-08-02', NULL, 11, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (250, 31, 84, 2, 'Add rollup regression coverage', 'Extend deterministic fixtures and unit/contract tests for CheckRun, StatusContext, mixed, completed-null, unknown, and failure-precedence cases', 'done', '2026-08-02', NULL, 11, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (251, 31, 84, 3, 'Add watcher wake regression', 'Prove queued plus successful checks emit pending without green owner wake, then green only after terminal success', 'done', '2026-08-02', NULL, 11, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (252, 31, 84, 4, 'Verification', 'Run focused and project checks, verify the spec done-condition, map/render/verify, and inspect the final diff', 'done', '2026-08-02', NULL, 11, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (253, 31, 85, 0, 'Preparation', 'Read the current sprint reconciler, wake-outbox schema and claim path, and existing recovery-test fixtures; confirm the no-migration entry points.', 'done', '2026-08-02', NULL, 5, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (254, 31, 85, 1, 'Implement busy-contention recovery', 'Classify SHELL_BUSY pickup failures, derive a durable ordinal chain with scheduled backoff, dedupe existing relinks/events, and pause with one Planner notice on exhaustion while preserving non-contention behavior.', 'done', '2026-08-02', NULL, 5, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (255, 31, 85, 2, 'Add regression coverage', 'Cover chained retries, durable restart counting, read/pickup stop conditions, attempt-five escalation and notice detail, non-busy one-shot behavior, deduped pulses, and available_at delivery gating.', 'done', '2026-08-02', NULL, 5, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (256, 31, 85, 3, 'Verification', 'Run focused sprint recovery/domain/delivery tests, then engine render-check, verify, map, and diff checks required by source maintenance.', 'done', '2026-08-02', NULL, 5, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (257, 31, 84, 5, 'CI verification', 'Require the GitHub full test suite and verify jobs to pass on the exact PR commit', 'done', '2026-08-02', NULL, 11, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (258, 31, 85, 4, 'Reset contention episode on resume', 'Re-deliver the stranded recovery wake immediately with a fresh episode namespace and make resume report the final active/paused outcome truthfully.', 'done', '2026-08-02', NULL, 5, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (259, 31, 85, 5, 'Review-fix verification', 'Add regression coverage for episode reset and changed semantics; run focused and source-maintenance verification before re-review.', 'done', '2026-08-02', NULL, 5, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (260, 31, 89, 1, 'Registry migration + fail-loud chat creation', 'Active-chat registry table (shell_id UNIQUE, chat_id, process_pid, process_start_ticks, updated_at). Close-first fail-loud creation ordering: close old chat + clear row, commit, then insert new chat + registry row + enqueue wake turn. Pid + start_ticks registered in the same transaction as run start; broker clears pid in the run-finalize write. One-chat rule universal — no sprint-scope exemption, idle human chats displaceable.', 'pending', NULL, NULL, 1, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (261, 31, 89, 2, 'wake_message rename + delivery-time type resolution, one producer', 'Rename sprint_messages→wake_message (sprint scope optional, receiver keyed on shell; acceptance semantics unchanged). Unify the two wake producers into one. Delivery-time type rule (decisions #65/#66): live verified turn→Re-enter at run boundary; idle→honor declared type (any New in coalesced set rotates, all-Re-enter spawns run in existing chat); no registry row→New. Wake turn drains ALL undelivered wake_messages. Outbox keeps idx_sprint_wake_one_pending_participant, no type column. Retire the active suppression flag.', 'pending', NULL, NULL, 1, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (262, 31, 89, 3, 'Reaper service + persisted process identity', '60s heartbeat. Candidates from run rows (pid + start_ticks + pgroup persisted at spawn); protected iff matching a registry row; /proc/pid/stat identity verify before any signal. Ladder on the process group: harness interrupt → TERM ~15s → KILL ~15s, ladder state persisted on the run row so escalation spans beats; reaper writes terminal interrupted status. ~30s young-process grace. Sandbox seats: reaper runs inside the container (pid-namespace visibility) + real init. Generalizes decision #40 into the shared runner.', 'pending', NULL, NULL, 1, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (263, 31, 89, 4, 'Activity monitor rewire + required inactivity ceiling + backoff', '3-attempt wake budget → close chat → clear registry → reaper → auto-pause (wake_delivery_exhausted). available_at backoff on failed attempts (fixes burn-in-10s defect). REQUIRED inactivity ceiling: active chat with no run evidence past configurable ceiling (default 45–60min) closed then reaped; queued wakes dispatch at that close. Decide trigger wiring (timer vs liveness escalation) in this unit — open item 1. Auto-pause preserves the coordinate flag.', 'pending', NULL, NULL, 1, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (264, 31, 89, 5, 'Routing table + coordinate flag + FnB close', 'Sprint routing: Planner→Dev New, Dev→Rev New, Rev→Dev Re-enter, Dev/Rev→Planner Re-enter (all idle-time guarantees under the delivery rule). Coordinate flag: FnB close of planner chat mid-sprint sets it; while set planner-bound Re-enter behaves as declared New; ONLY FnB-initiated close/pause/cancel clears it. FnB close works on any chat any time: chat closed + registry cleared, reaper takes the process.', 'pending', NULL, NULL, 1, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (265, 31, 89, 6, 'Engine-wide PR subscriptions + always-on watcher', 'Dev-owned subscription registrations replace hardcoded role×state routing; armed-sprint-only gate removed (watcher runs whenever registrations exist). Events to owning dev only, all Re-enter: red=fix, green=judge+baton to rev, closed=judge+inform planner. Every wake body carries PR identity (repo, number, head SHA, event) — cross-unit deliveries self-describing. No git wakes to Planner/Rev; merged PRs stay programmatic (decision #36 preserved).', 'pending', NULL, NULL, 1, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (266, 31, 89, 7, 'Arming flow + model-selection gate', 'Arm always sends New to the overseeing Planner (closes planner''s own chat if idle-open — intended); chat opens with per-role model selection prefilled with defaults. Dispatch gated on selections recorded — defaults satisfy the gate. Re-use the existing arming-modal pickers, no new UI surface. Selections write per-participant harness/model/effort. Replaces the v2.0 interview.', 'pending', NULL, NULL, 1, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (267, 31, 89, 8, 'Authority split protocols (sprint_pln + sprint_rev)', 'Ratified decision #67 (supersedes #53): Rev decides and documents — pause/cancel/conclude decisions, conformance doc, sprint report; Planner acts by protocol on Rev decision messages (Re-enter). Action protocols extend sprint_pln; report authorship moves into sprint_rev; Dev = code + owned-PR monitoring. FnB board override (decision #46) unaffected.', 'pending', NULL, NULL, 1, '2026-08-02');
INSERT INTO spec_tasks (task_id, feature_id, document_id, seq, title, description, status, completed_date, resolution_notes, shell_id, created_date) VALUES (268, 31, 89, 9, 'Skills + boot docs fold-in, retirements, test sweep', 'Retire the 9 subsystems (pointer columns — re-inventory the six+ live writers first; purpose taxonomy; reroute-chain scanning; deferred-close machinery; active flag; sprint-scope exemption; divergent producers; hand-rolled wake cancellation; armed-only gate). Fold v2.1 semantics into role skills + boot docs. Full regression sweep; retirements land only after replacements proven.', 'pending', NULL, NULL, 1, '2026-08-02');

