INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (318, 9, 5, 'Implementation handoff: Feature #23 / spec doc #30 — Shell-facing API identity wording.

