INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (1070, 6, 8, 'sprint 74: unit 2 ready for review — PR #934, checks green at 434c7cf. Please independently verify the audit matrix in the PR body against the diff, usage: sc mem get [-h] [--all] [--json] [--feature FEATURE] [--doc DOC]
