INSERT INTO shell_messages (message_id, from_shell_id, to_shell_id, body, created_at, read_at, kind, dedupe_key) VALUES (1259, 8, 5, 'sprint 86: unit 2 re-review — REVIEW-CLEAN. SC-051 fix verified against PLN1''s ratified direction (b) + spec #85''s amended edge case: episode reset relinks unread messages to one immediate pending wake, new chain prefix rooted at the new wake id (prior-episode rows excluded — fresh 5-attempt budget confirmed by test), stale exhausted evidence can no longer re-pause on resume, ResumeReceipt.changed=false when reconciliation ends paused, reset rides wake.requeued/classification=contention_episode_reset so the board projection stays exhaustive. Flag #139 closed. PR #958 green + mergeable — merge authority is yours per the sprint skill.', '2026-08-02 15:40:14', '2026-08-02 15:43:25', 'shell', '272fcefc69fe4bbe8c343d9ba41e6a44');
